import { extensionFor, type AllowedImageType } from './image';

const PATH_RE =
  /^covers\/\d{4}\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$/;

/** Storage object paths are always generated by the server, never taken from the client. */
export function newUploadPath(type: AllowedImageType, now: Date = new Date()): string {
  return `covers/${now.getUTCFullYear()}/${crypto.randomUUID()}.${extensionFor(type)}`;
}

export const isValidUploadPath = (path: string): boolean => PATH_RE.test(path);
